/* ===== 📥 Tally sales → how often each party buys → Customer Master + SCOT (26-Oct-2026) =====
 * CRM → SCOT → "Tally → frequency": paste the Tally Sales Register (or Day Book) copied from Excel.
 * Per party: bills in the last 6 months, average gap between bills (days), average bill value, usual bill date, last bill, 12-month value.
 * Saved in Script Properties TALLY_FREQ_* (no new sheet); the CRM stats job uses them so portal orders do not overwrite them.
 * SCOT: Average Order Size / Order Frequency / Usual Order Date updated, and the call day = usual date − 5 (calls per month kept). */
function tallyDate_(s) {
  if (s instanceof Date) return s; s = String(s || '').trim(); if (!s) return null;
  if (/^\d{5}(\.\d+)?$/.test(s)) { const d = new Date(Math.round((Number(s) - 25569) * 864e5)); return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }
  const MON = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };
  let m = s.match(/^(\d{1,2})[-\/. ]([A-Za-z]{3})[A-Za-z]*[-\/. ,]+(\d{2,4})/);
  if (m && MON[m[2].toLowerCase()] !== undefined) { let y = +m[3]; if (y < 100) y += 2000; return new Date(y, MON[m[2].toLowerCase()], +m[1]); }
  m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/); if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2,4})/); if (m) { let y = +m[3]; if (y < 100) y += 2000; return new Date(y, +m[2] - 1, +m[1]); }
  return null;
}
function tallyFreqParse_(text) {
  const L = String(text || '').split(/\r?\n/).map(l => l.split('\t').map(x => String(x).trim()));
  const hi = L.findIndex(r => r.some(x => /^date$/i.test(x)) && r.some(x => /^particulars/i.test(x)));
  if (hi < 0) throw new Error('Heading row not found — copy the rows WITH the heading row (Date, Particulars, Vch No, Value / Debit)');
  const H = L[hi], col = re => H.findIndex(x => re.test(x));
  const cD = col(/^date$/i), cP = col(/^particulars/i), cT = col(/^vch\.?\s*type|^voucher\s*type/i), cN = col(/^vch\.?\s*no|^voucher\s*no/i);
  let cV = col(/^(value|gross\s*total|amount|invoice\s*value|total)$/i); if (cV < 0) cV = col(/^debit/i); if (cV < 0) cV = col(/^credit/i);
  const bills = {}; let lastD = null, skipped = 0;
  L.slice(hi + 1).forEach(r => {
    const d = tallyDate_(r[cD]) || (r[cD] ? null : lastD); if (r[cD] && d) lastD = d;
    const p = String(r[cP] || '').trim(); if (!d || !p || /^(grand\s*)?total|^opening|^closing/i.test(p)) return;
    if (cT > -1 && r[cT] && !/sale/i.test(r[cT])) { skipped++; return; }
    if (cT > -1 && /credit\s*note|return/i.test(r[cT] || '')) { skipped++; return; }
    const v = cV > -1 ? Math.abs(Number(String(r[cV] || '').replace(/[^0-9.\-]/g, '')) || 0) : 0;
    const key = normName_(p) + '|' + (cN > -1 && r[cN] ? r[cN] : d.getTime());
    const b = bills[key] = bills[key] || { party: p, d, v: 0 }; b.v += v;
  });
  return { bills: Object.values(bills), skipped };
}
function tallyFreqStats_(bills) {
  if (!bills.length) throw new Error('No sales bills found in the pasted rows');
  const ref = new Date(Math.max.apply(null, bills.map(b => b.d.getTime()))), d6 = ref.getTime() - 182 * 864e5, d12 = ref.getTime() - 365 * 864e5;
  const by = {}; bills.forEach(b => { const k = normName_(b.party); (by[k] = by[k] || { name: b.party, B: [] }).B.push(b); });
  const S = {};
