    const B = by[k].B.sort((a, b) => a.d - b.d), day = {}; B.forEach(b => { const t = b.d.getTime(); day[t] = (day[t] || 0) + b.v; });
    const D = Object.keys(day).map(Number).sort((a, b) => a - b);
    let W = D.filter(t => t >= d6); if (W.length < 2) W = D.filter(t => t >= d12);
    const gaps = []; for (let j = 1; j < W.length; j++) gaps.push((W[j] - W[j - 1]) / 864e5);
    const n6 = B.filter(b => b.d.getTime() >= d6).length, V = B.filter(b => b.d.getTime() >= (n6 ? d6 : d12));
